const cp = require('child_process'); const fs = require('fs');
const s = (r) => JSON.stringify({ status: r.status, stdout: r.stdout == null ? null : String(r.stdout), stderr: r.stderr == null ? null : String(r.stderr), output: r.output && r.output.map((x) => (x == null ? null : String(x))) });
console.log('pipe', s(cp.spawnSync('sh', ['-c', 'echo o; echo e >&2'], { stdio: 'pipe' })));
console.log('ignore', s(cp.spawnSync('sh', ['-c', 'echo o; echo e >&2'], { stdio: 'ignore' })));
console.log('array', s(cp.spawnSync('sh', ['-c', 'echo o; echo e >&2'], { stdio: ['pipe', 'pipe', 'ignore'] })));
console.log('array2', s(cp.spawnSync('sh', ['-c', 'echo o; echo e >&2'], { stdio: ['ignore', 'ignore', 'pipe'] })));
console.log('--inherit next (child writes to our stdout)');
console.log('inherit', s(cp.spawnSync('sh', ['-c', 'echo INHERITED-OUT'], { stdio: 'inherit' })));
console.log('inherit-stderr-to-stdout', s(cp.spawnSync('sh', ['-c', 'echo E1 >&2'], { stdio: ['ignore', 'pipe', 1] })));
const fd = fs.openSync('/tmp/remap-out.txt', 'w');
const r = cp.spawnSync('sh', ['-c', 'head -c 3000000 /dev/zero; echo tail'], { stdio: ['ignore', fd, 'pipe'] }); fs.closeSync(fd);
console.log('fd remap (no maxBuffer)', r.status, r.error && r.error.code, fs.statSync('/tmp/remap-out.txt').size);
console.log('execSync stdio inherit returns', JSON.stringify(cp.execSync('echo VIA-INHERIT', { stdio: 'inherit' })));
console.log('execSync default stderr inherited:'); cp.execSync('echo ERR-INHERITED >&2');
